// convertPlaceholders converts SQLite-style ? placeholders to PostgreSQL-style $1, $2, etc.
// when running on PostgreSQL
func (t *FASetup) convertPlaceholders(sql string, count int) string {
	if t.dbType != database.DBTypePostgres {
		return sql
	}
	result := sql
	for i := 1; i <= count; i++ {
		result = strings.Replace(result, "?", fmt.Sprintf("$%d", i), 1)
	}
	return result
}

// Get retrieves a record from the database by primary key (interface{} for generic API)
// For single primary key: pass the value directly (string, int, etc.)
// For composite keys: pass a map[string]interface{} with field names as keys
func (t *FASetup) Get(primaryKey interface{}) bool {
	// Handle composite primary key (map[string]interface{})
	if pkMap, ok := primaryKey.(map[string]interface{}); ok {
		var primary_keyVal types.Code
		if v, exists := pkMap["primary_key"]; exists {
			switch val := v.(type) {
			case types.Code:
				primary_keyVal = val
			case string:
				primary_keyVal = types.NewCode(val)
			}
		}
		return t.GetByPK(primary_keyVal)
	}
	// Handle single primary key (for tables with only one PK field)
	switch pk := primaryKey.(type) {
	case types.Code:
		return t.GetByPK(pk)
	case string:
		return t.GetByPK(types.NewCode(pk))
	}

	fmt.Printf("Error: Invalid primary key type for FA_Setup.Get: %T (use map for composite keys)\n", primaryKey)
	return false
}

// GetByPK retrieves a record by its typed primary key(s) - for direct typed access
func (t *FASetup) GetByPK(primary_key types.Code) bool {
	tableName := fmt.Sprintf("%s$%s", t.company, FASetupTableName)
	var primary_keyNull sql.NullString
	var allow_posting_to_main_assetsBool sql.NullBool
	var default_depr_bookNull sql.NullString
	var allow_fa_posting_fromNull sql.NullString
	var allow_fa_posting_toNull sql.NullString
	var insurance_depr_bookNull sql.NullString
	var automatic_insurance_postingBool sql.NullBool
	var fixed_asset_nosNull sql.NullString
	var insurance_nosNull sql.NullString

	// Collect arguments for query
	args := []interface{}{
		primary_key,
	}

	// Build SQL with placeholders
	sqlStr := fmt.Sprintf(`SELECT primary_key, allow_posting_to_main_assets, default_depr_book, allow_fa_posting_from, allow_fa_posting_to, insurance_depr_book, automatic_insurance_posting, fixed_asset_nos, insurance_nos FROM "%s" WHERE 1=1 AND primary_key = ?`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))
	sqlStr += t.forUpdate()

	err := t.exec().QueryRow(sqlStr, args...).Scan(
		&primary_keyNull,
		&allow_posting_to_main_assetsBool,
		&default_depr_bookNull,
		&allow_fa_posting_fromNull,
		&allow_fa_posting_toNull,
		&insurance_depr_bookNull,
		&automatic_insurance_postingBool,
		&fixed_asset_nosNull,
		&insurance_nosNull,
	)

	if err != nil {
		if err == sql.ErrNoRows {
			// Record not found - this is not an error, just return false
			return false
		}
		// Actual database error
		fmt.Printf("Error: Failed to get FA_Setup: %v\n", err)
		return false
	}

	// Populate fields
	t.Primary_key = types.NewCode(primary_keyNull.String)
	t.Allow_posting_to_main_assets = allow_posting_to_main_assetsBool.Bool
	t.Default_depr_book = types.NewCode(default_depr_bookNull.String)
	t.Allow_fa_posting_from, _ = types.NewDateFromString(allow_fa_posting_fromNull.String)
	t.Allow_fa_posting_to, _ = types.NewDateFromString(allow_fa_posting_toNull.String)
	t.Insurance_depr_book = types.NewCode(insurance_depr_bookNull.String)
	t.Automatic_insurance_posting = automatic_insurance_postingBool.Bool
	t.Fixed_asset_nos = types.NewCode(fixed_asset_nosNull.String)
	t.Insurance_nos = types.NewCode(insurance_nosNull.String)

	// Store old values for field tracking
	t.StoreOldValues()

	return true
}

// Insert inserts the record into the database
func (t *FASetup) Insert(runTrigger bool) bool {
	// OnInsert trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnInsert(); err != nil {
			fmt.Printf("Error: OnInsert trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, FASetupTableName)

	// Collect arguments for INSERT
	args := []interface{}{
		t.Primary_key,
		t.Allow_posting_to_main_assets,
		t.Default_depr_book,
		t.Allow_fa_posting_from,
		t.Allow_fa_posting_to,
		t.Insurance_depr_book,
		t.Automatic_insurance_posting,
		t.Fixed_asset_nos,
		t.Insurance_nos,
	}

	// Build SQL with placeholders. A taken key inserts nothing (ON CONFLICT … DO NOTHING) instead
	// of failing: on PostgreSQL a failed INSERT would abort the transaction
	sqlStr := fmt.Sprintf(`INSERT INTO "%s" (primary_key, allow_posting_to_main_assets, default_depr_book, allow_fa_posting_from, allow_fa_posting_to, insurance_depr_book, automatic_insurance_posting, fixed_asset_nos, insurance_nos) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT (primary_key) DO NOTHING`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))

	result, err := t.exec().Exec(sqlStr, args...)
	if err != nil {
		fmt.Printf("Error: Failed to insert FA_Setup: %v\n", err)
		return false
	}
	// The key is taken (INSERT fails in the classic way: "<Table> <key> already exists")
	if n, err := result.RowsAffected(); err == nil && n == 0 {
		_, key := t.recordKey()
		t.triggerErr = apperrors.TableRecordExists(FASetupTableName, key)
		return false
	}
	// The record as written: its xRec from now on (a following Modify or Rename compares with it)
	t.StoreOldValues()
	return true
}

// InsertAll inserts records in bulk (demo data, imports): multi-row INSERT statements, one
// round trip per batch instead of one per record. With runTrigger every record's OnInsert
// trigger runs first, as Insert(true) would; the first failure stops before anything is
// written. Records are written with the receiver's database and company. Errors are
// *tables.BatchInsertError (Index = the record in records). Use it in a transaction: a
// failed batch leaves the earlier batches written.
func (t *FASetup) InsertAll(records []*FASetup, runTrigger bool) error {
	rows := make([][]interface{}, 0, len(records))
	for i, r := range records {
		r.triggerErr = nil
		if runTrigger {
			if err := r.runOnInsert(); err != nil {
				r.triggerErr = err
				return &tables.BatchInsertError{Index: i, Trigger: true, Err: err}
			}
		}
		rows = append(rows, []interface{}{
			r.Primary_key,
			r.Allow_posting_to_main_assets,
			r.Default_depr_book,
			r.Allow_fa_posting_from,
			r.Allow_fa_posting_to,
			r.Insurance_depr_book,
			r.Automatic_insurance_posting,
			r.Fixed_asset_nos,
			r.Insurance_nos,
		})
	}
	tableName := fmt.Sprintf("%s$%s", t.company, FASetupTableName)
	columns := []string{"primary_key", "allow_posting_to_main_assets", "default_depr_book", "allow_fa_posting_from", "allow_fa_posting_to", "insurance_depr_book", "automatic_insurance_posting", "fixed_asset_nos", "insurance_nos"}
	return tables.InsertRows(t.exec(), t.dbType, tableName, columns, rows)
}

// Modify updates the record in the database
func (t *FASetup) Modify(runTrigger bool) bool {
	// OnModify trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnModify(); err != nil {
			fmt.Printf("Error: OnModify trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	// A changed primary key is a rename: run the OnRename trigger
	// before it is written; xRec values are available through OldValue
	keyChanged := false
	if t.oldValues != nil {
		if t.hasFieldChanged("primary_key") {
			keyChanged = true
		}
	}
	if runTrigger && keyChanged {
		if err := t.runOnRename(); err != nil {
			fmt.Printf("Error: OnRename trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, FASetupTableName)

	// Build dynamic SQL based on field tracking
	var setClauses []string
	var values []interface{}

	// If we have old values (loaded from Get), only update changed fields.
	// Changed primary key fields are renamed in place (Rename): they are SET to the
	// new value while the WHERE clause matches the old one.
	if t.oldValues != nil {
		if t.hasFieldChanged("primary_key") {
			setClauses = append(setClauses, "primary_key = ?")
			values = append(values, t.Primary_key)
		}
		if t.hasFieldChanged("allow_posting_to_main_assets") {
			setClauses = append(setClauses, "allow_posting_to_main_assets = ?")
			values = append(values, t.Allow_posting_to_main_assets)
		}
		if t.hasFieldChanged("default_depr_book") {
			setClauses = append(setClauses, "default_depr_book = ?")
			values = append(values, t.Default_depr_book)
		}
		if t.hasFieldChanged("allow_fa_posting_from") {
			setClauses = append(setClauses, "allow_fa_posting_from = ?")
			values = append(values, t.Allow_fa_posting_from)
		}
		if t.hasFieldChanged("allow_fa_posting_to") {
			setClauses = append(setClauses, "allow_fa_posting_to = ?")
			values = append(values, t.Allow_fa_posting_to)
		}
		if t.hasFieldChanged("insurance_depr_book") {
			setClauses = append(setClauses, "insurance_depr_book = ?")
			values = append(values, t.Insurance_depr_book)
		}
		if t.hasFieldChanged("automatic_insurance_posting") {
			setClauses = append(setClauses, "automatic_insurance_posting = ?")
			values = append(values, t.Automatic_insurance_posting)
		}
		if t.hasFieldChanged("fixed_asset_nos") {
			setClauses = append(setClauses, "fixed_asset_nos = ?")
			values = append(values, t.Fixed_asset_nos)
		}
		if t.hasFieldChanged("insurance_nos") {
			setClauses = append(setClauses, "insurance_nos = ?")
			values = append(values, t.Insurance_nos)
		}

		// If nothing changed, skip update
		if len(setClauses) == 0 {
			return true // No changes, success
		}
	} else {
		// No old values (fresh record), update all fields
		setClauses = append(setClauses, "allow_posting_to_main_assets = ?")
		values = append(values, t.Allow_posting_to_main_assets)
		setClauses = append(setClauses, "default_depr_book = ?")
		values = append(values, t.Default_depr_book)
		setClauses = append(setClauses, "allow_fa_posting_from = ?")
		values = append(values, t.Allow_fa_posting_from)
		setClauses = append(setClauses, "allow_fa_posting_to = ?")
		values = append(values, t.Allow_fa_posting_to)
		setClauses = append(setClauses, "insurance_depr_book = ?")
		values = append(values, t.Insurance_depr_book)
		setClauses = append(setClauses, "automatic_insurance_posting = ?")
		values = append(values, t.Automatic_insurance_posting)
		setClauses = append(setClauses, "fixed_asset_nos = ?")
		values = append(values, t.Fixed_asset_nos)
		setClauses = append(setClauses, "insurance_nos = ?")
		values = append(values, t.Insurance_nos)
	}

	// Add WHERE clause value (primary key as loaded, so a renamed key still matches)
	if old, ok := t.oldValues["primary_key"]; ok {
		values = append(values, old)
	} else {
		values = append(values, t.Primary_key)
	}

	// Build and execute SQL
	sqlStr := fmt.Sprintf(`UPDATE "%s" SET %s WHERE 1=1 AND primary_key = ?`,
		tableName,
		strings.Join(setClauses, ", "),
	)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(values))

	_, err := t.exec().Exec(sqlStr, values...)
	if err != nil {
		fmt.Printf("Error: Failed to modify FA_Setup: %v\n", err)
		return false
	}
	// The stored record now matches the current values (including a renamed key)
	if t.oldValues != nil {
		t.StoreOldValues()
	}
	return true
}

// hasFieldChanged checks if a field value has changed from oldValues
func (t *FASetup) hasFieldChanged(fieldName string) bool {
	if t.oldValues == nil {
		return true // No old values, assume changed
	}

	oldValue, exists := t.oldValues[fieldName]
	if !exists {
		return true // Field not in old values, assume changed
	}
	_ = oldValue // Suppress unused variable when all fields are PKs

	// Compare old vs new value based on field name (with type assertion)
	switch fieldName {
	case "primary_key":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Primary_key.Equal(old)
		}
	case "allow_posting_to_main_assets":
		if old, ok := oldValue.(bool); ok {
			return t.Allow_posting_to_main_assets != old
		}
		return true // Type mismatch, assume changed
	case "default_depr_book":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Default_depr_book.Equal(old)
		}
	case "allow_fa_posting_from":
		if old, ok := oldValue.(types.Date); ok {
			return !t.Allow_fa_posting_from.Equal(old)
		}
	case "allow_fa_posting_to":
		if old, ok := oldValue.(types.Date); ok {
			return !t.Allow_fa_posting_to.Equal(old)
		}
	case "insurance_depr_book":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Insurance_depr_book.Equal(old)
		}
	case "automatic_insurance_posting":
		if old, ok := oldValue.(bool); ok {
			return t.Automatic_insurance_posting != old
		}
		return true // Type mismatch, assume changed
	case "fixed_asset_nos":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Fixed_asset_nos.Equal(old)
		}
	case "insurance_nos":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Insurance_nos.Equal(old)
		}
	}

	return false
}

