// FindSet opens a result set matching current filters
// Call Next() to iterate through the results
// Returns true if at least one record found, false otherwise
func (t *FASetup) FindSet() bool {
	// A temporary record, and a record in a transaction, reads all at once: its in-memory
	// database or the transaction has one connection, which an open result set would block for
	// the statements of the loop (Modify while looping; on PostgreSQL a query while the rows are
	// read breaks the connection — "unexpected Parse response")
	if _, inTx := t.db.(*sql.Tx); t.temp != nil || inTx {
		return t.FindSetBuffered()
	}
	// Close any existing result set
	if t.currentRows != nil {
		t.currentRows.Close()
		t.currentRows = nil
	}
	t.bufferedRecords = nil
	tableName := fmt.Sprintf("%s$%s", t.company, FASetupTableName)
	where, args := t.buildWhereClause()
	orderBy, orderArgs := t.getOrderByClause()
	args = append(args, orderArgs...)

	// Build SELECT with all fields
	query := fmt.Sprintf(`SELECT primary_key, allow_posting_to_main_assets, default_depr_book, allow_fa_posting_from, allow_fa_posting_to, insurance_depr_book, automatic_insurance_posting, fixed_asset_nos, insurance_nos FROM "%s" WHERE %s ORDER BY %s%s`, tableName, where, orderBy, t.getLimitClause())

	// Convert placeholders for PostgreSQL
	query = t.convertPlaceholders(query, len(args))
	query += t.forUpdate()

	rows, err := t.exec().Query(query, args...)
	if err != nil {
		fmt.Printf("Error: Failed to execute FindSet for FA_Setup: %v\n", err)
		return false
	}

	t.currentRows = rows

	// Load first record
	return t.Next()
}

// Next advances to the next record: in the result set after FindSet() or FindSetBuffered(),
// else from the current record in the current key (after Get, Find, FindFirst, FindLast)
// Optional steps parameter:
//   - Next() or Next(1): Move forward 1 record (default)
//   - Next(5): Skip forward 5 records
//   - Next(-1): Move backward 1 record (FindSetBuffered, or after Get/Find)
//   - Next(-3): Skip backward 3 records (FindSetBuffered, or after Get/Find)
//
// Returns true if a record was loaded, false if no more records or out of bounds
func (t *FASetup) Next(steps ...int) bool {
	// Default to 1 step forward
	step := 1
	if len(steps) > 0 {
		step = steps[0]
	}

	// BUFFERED MODE: Bidirectional navigation with in-memory records
	if t.bufferedRecords != nil {
		// Calculate new position
		newPos := t.currentBufferPos + step

		// Check bounds
		if newPos < 0 || newPos >= len(t.bufferedRecords) {
			return false // Out of bounds
		}

		// Move to new position
		t.currentBufferPos = newPos
		t.copyFromBuffered(t.bufferedRecords[t.currentBufferPos])
		return true
	}

	// FORWARD-ONLY MODE: Streaming with sql.Rows (only positive steps allowed)
	if t.currentRows != nil {
		// Validate: only forward movement allowed
		if step < 1 {
			fmt.Printf("Error: Backward navigation (Next(%d)) requires FindSetBuffered()\n", step)
			return false
		}

		// Advance 'step' times (1 = next record, 2 = skip 1 record, etc.)
		for i := 0; i < step; i++ {
			if !t.currentRows.Next() {
				// No more rows - close result set
				t.currentRows.Close()
				t.currentRows = nil
				return false
			}
		}

		// Scan the row
		var primary_keyNull sql.NullString
		var allow_posting_to_main_assetsBool sql.NullBool
		var default_depr_bookNull sql.NullString
		var allow_fa_posting_fromNull sql.NullString
		var allow_fa_posting_toNull sql.NullString
		var insurance_depr_bookNull sql.NullString
		var automatic_insurance_postingBool sql.NullBool
		var fixed_asset_nosNull sql.NullString
		var insurance_nosNull sql.NullString

		err := t.currentRows.Scan(
			&primary_keyNull,
			&allow_posting_to_main_assetsBool,
			&default_depr_bookNull,
			&allow_fa_posting_fromNull,
			&allow_fa_posting_toNull,
			&insurance_depr_bookNull,
			&automatic_insurance_postingBool,
			&fixed_asset_nosNull,
			&insurance_nosNull,
		)

		if err != nil {
			fmt.Printf("Error: Failed to scan FA_Setup record: %v\n", err)
			t.currentRows.Close()
			t.currentRows = nil
			return false
		}

		// Populate fields
		t.Primary_key = types.NewCode(primary_keyNull.String)
		t.Allow_posting_to_main_assets = allow_posting_to_main_assetsBool.Bool
		t.Default_depr_book = types.NewCode(default_depr_bookNull.String)
		t.Allow_fa_posting_from, _ = types.NewDateFromString(allow_fa_posting_fromNull.String)
		t.Allow_fa_posting_to, _ = types.NewDateFromString(allow_fa_posting_toNull.String)
		t.Insurance_depr_book = types.NewCode(insurance_depr_bookNull.String)
		t.Automatic_insurance_posting = automatic_insurance_postingBool.Bool
		t.Fixed_asset_nos = types.NewCode(fixed_asset_nosNull.String)
		t.Insurance_nos = types.NewCode(insurance_nosNull.String)

		// Store old values for field tracking
		t.StoreOldValues()

		return true
	}

	// No record set (after Get, Find, FindFirst, FindLast): the next record in the current key
	// and direction within the filters, one step at a time (classic NEXT after FIND); a step
	// that finds none leaves the record on the last one reached
	if step == 0 {
		return false
	}
	for i := 0; i != step; {
		if step > 0 {
			if !t.findInKey(">", false) {
				return false
			}
			i++
		} else {
			if !t.findInKey("<", true) {
				return false
			}
			i--
		}
	}
	return true
}

// FindSetBuffered loads all filtered records into memory for bidirectional navigation
// Use this when you need to move backward/forward with Next(steps)
// Filters (SetRange/SetFilter) are applied in SQL before buffering to minimize memory usage
// Returns true if at least one record found, false otherwise
func (t *FASetup) FindSetBuffered() bool {
	// Close any existing forward-only result set
	if t.currentRows != nil {
		t.currentRows.Close()
		t.currentRows = nil
	}

	// Clear any existing buffer
	t.bufferedRecords = nil
	t.currentBufferPos = -1
	tableName := fmt.Sprintf("%s$%s", t.company, FASetupTableName)
	where, args := t.buildWhereClause()
	orderBy, orderArgs := t.getOrderByClause()
	args = append(args, orderArgs...)

	// Build SELECT with all fields
	query := fmt.Sprintf(`SELECT primary_key, allow_posting_to_main_assets, default_depr_book, allow_fa_posting_from, allow_fa_posting_to, insurance_depr_book, automatic_insurance_posting, fixed_asset_nos, insurance_nos FROM "%s" WHERE %s ORDER BY %s%s`, tableName, where, orderBy, t.getLimitClause())

	// Convert placeholders for PostgreSQL
	query = t.convertPlaceholders(query, len(args))

	rows, err := t.exec().Query(query, args...)
	if err != nil {
		fmt.Printf("Error: Failed to execute FindSetBuffered for FA_Setup: %v\n", err)
		return false
	}
	defer rows.Close()

	// Load all records into memory
	for rows.Next() {
		// Create a new record instance
		record := &FASetup{}
		record.db = t.db
		record.temp = t.temp
		record.company = t.company
		record.dbType = t.dbType

		// Scan the row
		var primary_keyNull sql.NullString
		var allow_posting_to_main_assetsBool sql.NullBool
		var default_depr_bookNull sql.NullString
		var allow_fa_posting_fromNull sql.NullString
		var allow_fa_posting_toNull sql.NullString
		var insurance_depr_bookNull sql.NullString
		var automatic_insurance_postingBool sql.NullBool
		var fixed_asset_nosNull sql.NullString
		var insurance_nosNull sql.NullString

		err := rows.Scan(
			&primary_keyNull,
			&allow_posting_to_main_assetsBool,
			&default_depr_bookNull,
			&allow_fa_posting_fromNull,
			&allow_fa_posting_toNull,
			&insurance_depr_bookNull,
			&automatic_insurance_postingBool,
			&fixed_asset_nosNull,
			&insurance_nosNull,
		)

		if err != nil {
			fmt.Printf("Error: Failed to scan FA_Setup record: %v\n", err)
			return false
		}

		// Populate special type fields
		record.Primary_key = types.NewCode(primary_keyNull.String)
		record.Allow_posting_to_main_assets = allow_posting_to_main_assetsBool.Bool
		record.Default_depr_book = types.NewCode(default_depr_bookNull.String)
		record.Allow_fa_posting_from, _ = types.NewDateFromString(allow_fa_posting_fromNull.String)
		record.Allow_fa_posting_to, _ = types.NewDateFromString(allow_fa_posting_toNull.String)
		record.Insurance_depr_book = types.NewCode(insurance_depr_bookNull.String)
		record.Automatic_insurance_posting = automatic_insurance_postingBool.Bool
		record.Fixed_asset_nos = types.NewCode(fixed_asset_nosNull.String)
		record.Insurance_nos = types.NewCode(insurance_nosNull.String)

		// Store old values
		record.StoreOldValues()

		// Add to buffer
		t.bufferedRecords = append(t.bufferedRecords, record)
	}

	// Check for errors during iteration
	if err := rows.Err(); err != nil {
		fmt.Printf("Error: Failed to iterate FA_Setup records: %v\n", err)
		return false
	}

	// If no records found, return false
	if len(t.bufferedRecords) == 0 {
		return false
	}

	// Load first record into current instance
	t.currentBufferPos = 0
	t.copyFromBuffered(t.bufferedRecords[0])

	return true
}

// copyFromBuffered copies field values from a buffered record to the current instance
func (t *FASetup) copyFromBuffered(record *FASetup) {
	t.Primary_key = record.Primary_key
	t.Allow_posting_to_main_assets = record.Allow_posting_to_main_assets
	t.Default_depr_book = record.Default_depr_book
	t.Allow_fa_posting_from = record.Allow_fa_posting_from
	t.Allow_fa_posting_to = record.Allow_fa_posting_to
	t.Insurance_depr_book = record.Insurance_depr_book
	t.Automatic_insurance_posting = record.Automatic_insurance_posting
	t.Fixed_asset_nos = record.Fixed_asset_nos
	t.Insurance_nos = record.Insurance_nos
	t.StoreOldValues()
}

// ========================================
// Phase 3: Advanced Methods
// ========================================

// IsEmpty returns true if no records match current filters
func (t *FASetup) IsEmpty() bool {
	return t.Count() == 0
}

// ModifyAll updates a field for all records matching current filters
// Returns the number of records modified
func (t *FASetup) ModifyAll(fieldName string, newValue interface{}) int {
	tableName := fmt.Sprintf("%s$%s", t.company, FASetupTableName)
	column, ok := t.columnName(fieldName)
	if !ok {
		fmt.Printf("Error: ModifyAll on unknown field %q of FA_Setup\n", fieldName)
		return 0
	}
	where, args := t.buildWhereClause()

	// Build UPDATE SQL
	updateSQL := fmt.Sprintf(`UPDATE "%s" SET %s = ? WHERE %s`, tableName, column, where)

	// Prepend newValue to args
	allArgs := append([]interface{}{newValue}, args...)

	// Convert placeholders for PostgreSQL
	updateSQL = t.convertPlaceholders(updateSQL, len(allArgs))

	result, err := t.exec().Exec(updateSQL, allArgs...)
	if err != nil {
		fmt.Printf("Error: Failed to modify all FA_Setup: %v\n", err)
		return 0
	}

	rowsAffected, _ := result.RowsAffected()
	return int(rowsAffected)
}

// DeleteAll deletes all records matching current filters
// Returns the number of records deleted
func (t *FASetup) DeleteAll() int {
	tableName := fmt.Sprintf("%s$%s", t.company, FASetupTableName)
	where, args := t.buildWhereClause()

	// Build DELETE SQL
	deleteSQL := fmt.Sprintf(`DELETE FROM "%s" WHERE %s`, tableName, where)

	// Convert placeholders for PostgreSQL
	deleteSQL = t.convertPlaceholders(deleteSQL, len(args))

	result, err := t.exec().Exec(deleteSQL, args...)
	if err != nil {
		fmt.Printf("Error: Failed to delete all FA_Setup: %v\n", err)
		return 0
	}

	rowsAffected, _ := result.RowsAffected()
	return int(rowsAffected)
}

// CopyFilters copies filters from another record variable (all filter groups)
func (t *FASetup) CopyFilters(from *FASetup) {
	t.filters = copyFASetupFilters(from.filters)
	t.filterGroup = from.filterGroup
	t.otherFilters = nil
	for g, filters := range from.otherFilters {
		if t.otherFilters == nil {
			t.otherFilters = map[int]map[string]*fASetupFilterCondition{}
		}
		t.otherFilters[g] = copyFASetupFilters(filters)
	}

	// Also copy order by fields
	if len(from.orderByFields) > 0 {
		t.orderByFields = make([]string, len(from.orderByFields))
		copy(t.orderByFields, from.orderByFields)
	} else {
		t.orderByFields = nil
	}
}

// copyFASetupFilters returns a deep copy of a filter group's filters (nil for none)
func copyFASetupFilters(from map[string]*fASetupFilterCondition) map[string]*fASetupFilterCondition {
	if from == nil {
		return nil
	}
	filters := make(map[string]*fASetupFilterCondition, len(from))
	for key, filter := range from {
		c := *filter
		filters[key] = &c
	}
	return filters
}

// GetFilters returns a string representation of current filters
// Useful for debugging and logging
func (t *FASetup) GetFilters() string {
	if len(t.filters) == 0 {
		return ""
	}

	var parts []string
	for _, filter := range t.filters {
		if filter.invalidField {
			parts = append(parts, "<invalid field>")
		} else if filter.isExpression {
			parts = append(parts, fmt.Sprintf("%s: %s", filter.fieldName, filter.filterExpr))
		} else if filter.minValue != nil && filter.maxValue != nil {
			parts = append(parts, fmt.Sprintf("%s: %v..%v", filter.fieldName, filter.minValue, filter.maxValue))
		} else if filter.minValue != nil {
			parts = append(parts, fmt.Sprintf("%s: >=%v", filter.fieldName, filter.minValue))
		} else if filter.maxValue != nil {
			parts = append(parts, fmt.Sprintf("%s: <=%v", filter.fieldName, filter.maxValue))
		}
	}

	return strings.Join(parts, ", ")
}

